/// <summary>
/// Data contract class as a response for service <c>METSalesOrderCancelService</c>
/// </summary>
[DataContractAttribute]
class METBaseResponseContract
{
    String10            cancelResult; //string for enum METProcessingStatus
    Description255      cancelMessage;

}

Method.Source:
/// <summary>
/// Method returns true if sales order is cancelled/else false
/// </summary>
/// <param name = "_cancelResult">a boolean value indicating the sales cancellation result</param>
/// <returns>returns true if sales order is cancelled/else false</returns>
[DataMemberAttribute('Result')]
public String10 parmCancelResult(String10 _cancelResult = cancelResult)
{
    cancelResult = _cancelResult;
    return cancelResult;
}

/// <summary>
/// This method returns the message corresponding to the sales order cancellation
/// </summary>
/// <param name = "_cancelMessage">a string value specifying the sales cancellation result</param>
/// <returns>returns the message corresponding to the sales order cancellation</returns>
[DataMemberAttribute('Message')]
public Description255 parmCancelMessage(Description255 _cancelMessage = cancelMessage)
{
    cancelMessage = _cancelMessage;
    return cancelMessage;
}
